#include "server1/archive/TarSource.h"
#include "server1/archive/GzipSource.h"
#include <QCoreApplication>
#include <QEventLoop>
#include <QTimer>
#include <QFile>
#include <QJsonDocument>
#include <QSet>
#include <iostream>
using namespace server1::archive;
struct MemorySource {
 QByteArray bytes;QObject *owner;quint64 next=0;QSet<quint64> pending;int reads=0,cancels=0;qint64 largest=0;
 MemorySource(QByteArray data,QObject *context):bytes(std::move(data)),owner(context){}
 ZipSource::Read reader(){return [this](qint64 offset,qint64 count,RemoteByteSource::Completion cb){auto token=++next;pending.insert(token);++reads;largest=qMax(largest,count);QTimer::singleShot(0,owner,[this,offset,count,token,cb=std::move(cb)](){if(!pending.remove(token))return;cb({offset>=0&&offset<bytes.size()?bytes.mid(offset,count):QByteArray(),{},206,bytes.size()});});return token;};}
 ZipSource::Cancel cancel(){return [this](quint64 token){if(pending.remove(token))++cancels;};}
};
static bool until(const std::function<bool()> &done){QEventLoop loop;QTimer timer;timer.setInterval(1);QObject::connect(&timer,&QTimer::timeout,&loop,[&](){if(done())loop.quit();});timer.start();QTimer::singleShot(3000,&loop,&QEventLoop::quit);if(!done())loop.exec();return done();}
int main(int argc,char**argv){QCoreApplication app(argc,argv);if(argc!=2)return 2;QFile file(argv[1]);if(!file.open(QIODevice::ReadOnly))return 2;auto root=QJsonDocument::fromJson(file.readAll()).object();int failures=0,checks=0;auto check=[&](bool ok,const QString&msg){++checks;if(!ok){++failures;std::cerr<<msg.toStdString()<<'\n';}};
 for(auto value:root["rows"].toArray()){auto row=value.toObject(),expected=row["expected"].toObject();bool streaming=row["id"].toInt()==1304;QString label=row["name"].toString()+QString::number(row["id"].toInt());MemorySource memory{QByteArray::fromBase64(row[streaming?"gzip":"archive"].toString().toLatin1()),&app};GzipReader gzip(memory.bytes.size(),memory.reader(),memory.cancel());ZipSource::Read read=streaming?ZipSource::Read([&](qint64 at,qint64 n,RemoteByteSource::Completion cb){return gzip.readForward(at,n,std::move(cb));}):memory.reader();ZipSource::Cancel cancel=streaming?ZipSource::Cancel([&](quint64 t){gzip.cancel(t);}):memory.cancel();TarSource source(streaming?-1:memory.bytes.size(),read,cancel,nullptr,streaming);bool done=false;TarEntry entry;QString error;int index=0;source.find([&](const TarEntry&){return index++==row["index"].toInt();},[&](TarEntry e,QString err){entry=std::move(e);error=err;done=true;});check(until([&](){return done;}),label+" selection timeout");if(expected.contains("error")){check(error==expected["error"].toString(),label+" error: "+error);continue;}check(error.isEmpty(),label+" unexpected error "+error);check(entry.name==expected["name"].toString(),label+" name");check(entry.type==expected["type"].toString(),label+" type");check(entry.linkname==expected["linkname"].toString(),label+" link");check(entry.size==expected["size"].toInteger(),label+" size");check(entry.offset==expected["offset"].toInteger(),label+" offset");check(entry.dataOffset==expected["dataOffset"].toInteger(),label+" dataOffset");check(entry.pax==expected["pax"].toObject(),label+" pax");if(expected.contains("body")){TarEntryReader reader(entry,read,cancel);QByteArray data;bool eof=false;for(int i=0;!eof&&i<100;++i){bool pulled=false;reader.pull(2,[&](ZipChunk c){data+=c.bytes;error=c.error;eof=c.eof;pulled=true;});check(until([&](){return pulled;}),label+" read timeout");}check(error.isEmpty()&&eof&&data==QByteArray::fromBase64(expected["body"].toString().toLatin1()),label+" body");}if(streaming&&entry.size){TarEntryReader reader(entry,read,cancel);QByteArray data;bool eof=false;for(int i=0;!eof&&i<100;++i){bool pulled=false;reader.pull(2,[&](ZipChunk c){data+=c.bytes;error=c.error;eof=c.eof;pulled=true;});check(until([&](){return pulled;}),label+" TGZ timeout");}auto raw=QByteArray::fromBase64(row["archive"].toString().toLatin1());check(error.isEmpty()&&eof&&data==raw.mid(entry.streamOffset,entry.size),label+" TGZ body");}check(memory.largest<=65536,label+" input bound");}
 for(auto value:root["gzip"].toArray()){auto row=value.toObject();MemorySource memory{QByteArray::fromBase64(row["data"].toString().toLatin1()),&app};GzipReader reader(memory.bytes.size(),memory.reader(),memory.cancel());QByteArray output;bool eof=false;QString error;check(memory.reads==0,"gzip lazy start");for(int i=0;i<1000&&!eof;++i){bool done=false;reader.pull(4093,[&](ZipChunk c){output+=c.bytes;eof=c.eof;error=c.error;done=true;});check(until([&](){return done;}),"gzip pull timeout");}check(eof&&error.isEmpty()&&output==QByteArray::fromBase64(row["body"].toString().toLatin1()),"gzip "+row["name"].toString()+" "+error);check(memory.largest<=65536,"gzip bounded input");}
 // Truncation, CRC failure, forward-only policy, lazy pull, and cancellation.
 auto sample=QByteArray::fromBase64(root["gzip"].toArray()[1].toObject()["data"].toString().toLatin1());for(int kind=0;kind<2;++kind){auto bytes=sample;if(kind==0)bytes.chop(4);else bytes[bytes.size()-8]^=1;MemorySource memory{bytes,&app};GzipReader reader(bytes.size(),memory.reader(),memory.cancel());bool eof=false;QString error;for(int i=0;i<1000&&!eof;++i){bool done=false;reader.pull(65536,[&](ZipChunk c){error=c.error;eof=c.eof;done=true;});check(until([&](){return done;}),"invalid gzip timeout");}check(eof&&!error.isEmpty(),"gzip integrity/truncation failure");}
 {MemorySource memory{sample,&app};GzipReader reader(sample.size(),memory.reader(),memory.cancel());bool called=false;auto token=reader.readForward(0,512,[&](ReadResult){called=true;});reader.cancel(token);QCoreApplication::processEvents();check(!called&&memory.reads==0,"cancel before scheduled gzip read");}
 {MemorySource memory{sample,&app};GzipReader reader(sample.size(),memory.reader(),memory.cancel());bool called=false;reader.pull(512,[&](ZipChunk){called=true;});QCoreApplication::processEvents();reader.cancel();QCoreApplication::processEvents();check(!called&&memory.pending.isEmpty(),"cancel pending gzip source read");}
 {MemorySource memory{sample,&app};GzipReader reader(sample.size(),memory.reader(),memory.cancel());bool done=false;reader.readForward(10,20,[&](ReadResult r){check(r.bytes.size()==20&&r.error.isEmpty(),"forward skip/read");done=true;});check(until([&](){return done;}),"forward read timeout");done=false;reader.readForward(0,1,[&](ReadResult r){check(!r.error.isEmpty(),"backward read rejected");done=true;});check(until([&](){return done;}),"backward callback");}
 {MemorySource memory{QByteArray(512,'\0'),&app};TarSource source(512,memory.reader(),memory.cancel());bool called=false;source.find([](const TarEntry&){return true;},[&](TarEntry,QString){called=true;});source.cancel();QCoreApplication::processEvents();check(!called&&memory.reads==0,"cancel before TAR header");}
 std::cout<<"TAR/GZIP checks="<<checks<<" failures="<<failures<<'\n';return failures?1:0;}
